  <script>
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phonePattern = /^\+?[0-9\s().-]{7,}$/;

    function createField({ id, label, type, name, placeholder, required, helperText, value, error }) {
      return `
        <div class="form-field">
          <label for="${id}">${label}${required ? ' *' : ''}</label>
          <input
            id="${id}"
            name="${name}"
            type="${type}"
            placeholder="${placeholder}"
            value="${value}"
            ${required ? 'required' : ''}
            aria-invalid="${error ? 'true' : 'false'}"
            aria-describedby="${helperText ? `${id}-helper` : ''} ${id}-error".trim()
          />
          ${helperText ? `<p class="helper-text" id="${id}-helper">${helperText}</p>` : ''}
          <p class="error-text" id="${id}-error" role="alert" aria-live="polite">${error || ''}</p>
        </div>
      `;
    }

    function App() {
      const state = {
        values: {
          fullName: '',
          email: '',
          phone: '',
        },
        touched: {
          fullName: false,
          email: false,
          phone: false,
        },
        submitted: false,
        success: ''
      };

      const root = document.getElementById('root');

      function validate(values) {
        const errors = {};

        if (!values.fullName.trim()) {
          errors.fullName = 'Full name is required.';
        }

        if (!values.email.trim()) {
          errors.email = 'Email address is required.';
        } else if (!emailPattern.test(values.email.trim())) {
          errors.email = 'Enter a valid email address.';
        }

        if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
          errors.phone = 'Enter a valid phone number or leave it blank.';
        }

        return errors;
      }

      function render() {
        const errors = validate(state.values);
        const showError = (field) => state.touched[field] || state.submitted;
        root.innerHTML = `
          <section class="card" aria-labelledby="support-title">
            <header class="card-header">
              <h1 id="support-title">Contact Support</h1>
              <p class="subtext">Send a message and we will get back to you as soon as possible.</p>
            </header>
            <form novalidate>
              ${createField({
                id: 'fullName',
                label: 'Full name',
                type: 'text',
                name: 'fullName',
                placeholder: 'Alex Johnson',
                required: true,
                value: state.values.fullName,
                error: showError('fullName') ? errors.fullName : ''
              })}
              ${createField({
                id: 'email',
                label: 'Email address',
                type: 'email',
                name: 'email',
                placeholder: 'alex@example.com',
                required: true,
                value: state.values.email,
                error: showError('email') ? errors.email : ''
              })}
              ${createField({
                id: 'phone',
                label: 'Phone number',
                type: 'tel',
                name: 'phone',
                placeholder: '+1 (555) 123-4567',
                required: false,
                helperText: 'Optional. Use a number like +1 (555) 123-4567 or 555-123-4567.',
                value: state.values.phone,
                error: showError('phone') ? errors.phone : ''
              })}
              <div class="actions">
                <button type="submit">Submit</button>
              </div>
              <p class="success" aria-live="polite">${state.success}</p>
            </form>
          </section>
        `;

        const form = root.querySelector('form');
        form.addEventListener('submit', (event) => {
          event.preventDefault();
          state.submitted = true;
          const currentErrors = validate(state.values);
          if (Object.keys(currentErrors).length === 0) {
            state.success = 'Your message is ready to send.';
          } else {
            state.success = '';
          }
          render();
        });

        ['fullName', 'email', 'phone'].forEach((field) => {
