          input.addEventListener('input', (event) => {
            state.values[field] = event.target.value;
            state.success = '';
            render();
          });
          input.addEventListener('blur', () => {
            state.touched[field] = true;
            render();
          });
        });
      }

      render();
    }

    App();
  </script>
